,["ud5","UD5 - Movimentazione carichi e pazienti",45],["ud6","UD6 - Taglio e puntura",45],["ud7","UD7 - Chimici, cancerogeni, mutageni e amianto",60],["ud8","UD8 - Agenti biologici",60],["ud9","UD9 - Agenti fisici",45],["ud10","UD10 - Cenni sulle radiazioni ionizzanti",30],["ud11","UD11 - Incendio ed emergenze",45],["ud12","UD12 - Aggressioni, stress e burnout",60],["ud13","UD13 - Protezioni collettive e DPI",45],["ud14","UD14 - Atmosfere iperbariche",45],["ud15","UD15 - Rifiuti ospedalieri",45]]},{"key":"rspp_c","title":"RSPP - Modulo C - 24h","family":"RSPP","minutes":1440,"blueprint":"rspp_c","delivery":"physical_or_vcs","assessment":"interview","units":[["c1","C1 - Informazione, formazione, addestramento e progettazione formativa",480],["c2","C2 - Organizzazione e sistemi di gestione SSL",480],["c3","C3 - Relazioni, comunicazione, negoziazione e conflitti",240],["c4","C4 - Benessere organizzativo, ergonomia e fattori psicosociali",240]]},{"key":"agg_aspp","title":"Aggiornamento ASPP - 20h / 5 anni","family":"RSPP/ASPP","minutes":1200,"blueprint":"aspp_update","delivery":"physical_vcs_elearning","assessment":"test_or_interview","units":[["u1","Novità normative, tecniche e organizzative",240],["u2","Riesame dei rischi, metodi e dati",240],["u3","Infortuni, near miss, audit e indicatori",240],["u4","Efficacia delle misure e miglioramento",240],["u5","Competenze, coordinamento e approfondimenti professionali",240]]},{"key":"agg_rspp","title":"Aggiornamento RSPP - 40h / 5 anni","family":"RSPP/ASPP","minutes":2400,"blueprint":"rspp_update","delivery":"physical_vcs_elearning","assessment":"test_or_interview","units":[["u1","Novità normative, tecniche e organizzative",300],["u2","Riesame dei rischi, metodi e dati",300],["u3","Infortuni, near miss, audit e indicatori",300],["u4","Efficacia delle misure e miglioramento",300],["u5","Competenze, comunicazione e consultazione",300],["u6","Approfondimenti specialistici di settore",300],["u7","Sistemi di gestione e cambiamento