 public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_version,'program',spec->>'title',1,(spec->>'minutes')::int) returning id into v_module; p:=0; for u in select value from jsonb_array_elements(spec->'units') loop p:=p+1; insert into public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata) values('rspp-aspp:'||(spec->>'key')||':'||(u->>0),u->>1,'Unità RSPP/ASPP: '||(u->>1),(u->>2)::int,'rspp_aspp',array['rspp','aspp','asr-2025',spec->>'key'],true,jsonb_build_object('didactic_version','rspp-aspp-v2','official_ud',u->>0,'course_key',spec->>'key','internal_didactic_allocation',true)) on conflict(stable_key) do update set title=excluded.title,summary=excluded.summary,default_minutes=excluded.default_minutes,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=public.learning_units.metadata||excluded.metadata,updated_at=now() returning id into v_lu; insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at) values(v_lu,1,'published',jsonb_build_object('didactic_version','rspp-aspp-v2','official_ud',u->>0,'title',u->>1,'minutes',(u->>2)::int,'summary','Contestualizzare il tema, raccogliere evidenze e trasformare l’analisi in misure verificabili.','procedure',jsonb_build_array('Contesto','Evidenze','Pericoli','Valutazione','Misure','Responsabilità','Verifica','Riesame'),'final_assessment',false),now()) on conflict(learning_unit_id,version_number) do update set status='published',content=excluded.content,published_at=coalesce(public.learning_unit_versions.published_at,now()); select id into v_luv from public.learning_unit_versions where learning_unit_id=v_lu and version_number=1; insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules) values(v_module,v_luv,p,true,0,true,'{"didactic_version":"rspp-aspp-v2","final_assessment_separate":true}'::jsonb); end loop; update public.integration_course_catalog set mapped_course_id=v_course,delivery_status='needs_configuration',metadata=metadata||jsonb_build_object('mapped_course_key',spec->>'key','didactic_version','rspp-aspp-v2','publication_blocked',true),updated_at=now() where source_system='safetytraining' and external_course_code=spec->>'key'; if spec->>'key'='rspp_aspp_a' then insert into public.course_verification_requirements(course_version_id,requirement_key,title,verification_mode,minimum_questions,minimum_options_per_question,passing_score_pct,required,completion_mode,metadata) values(v_version,'final_test','Verifica Modulo A','test',30,3,70,true,'platform_or_external','{"supplementary_interview_allowed":true,"question_bank_complete":false}'::jsonb) on conflict(course_version_id,requirement_key) do update set verification_mode='test',minimum_questions=30,minimum_options_per_question=3,passing_score_pct=70,metadata=public.course_verification_requirements.metadata||excluded.metadata,updated_at=now(); elsif spec->>'key'='rspp_aspp_b' then insert into public.course_verification_requirements(course_version_id,requirement_key,title,verification_mode,minimum_questions,minimum_options_per_question,passing_score_pct,required,completion_mode,metadata) values(v_version,'final_test','Test Modulo B','test',30,3,70,true,'platform_or_external','{"scope":"common_plus_applicable_specializations","question_bank_complete":false}'::jsonb) on conflict(course_version_id,requirement_key) do update set verification_mode='test',minimum_questions=30,minimum_options_per_question=3,passing_score_pct=70,metadata=public.course_verification_requirements.metadata||excluded.metadata,updated_at=now(); insert into public.course_verification_requirements(course_version_id,requirement_key,title,verification_mode,required,completion_mode,metadata) values(v_version,'final_simulation','Simulazione Modulo B','simulation',true,'platform_or_external','{"scope":"common_plus_applicable_specializations"}'::jsonb) on conflict(course_version_id,requirement_key) do update set verification_mode='simulation',required=true,metadata=public.course_verification_requirements.metadata||excluded.metadata,updated_at=now(); elsif spec->>'key'='rspp_c' then insert into public.course_verification_requirements(course_version_id,requirement_key,title,verification_mode,required,completion_mode,metadata) values(v_version,'final_interview','Colloquio individuale Modulo C','interview',true,'external','{"question_bank_complete":false}'::jsonb) on conflict(course_version_id,requirement_key) do update set verification_mode='interview',required=true,completion_mode='external',metadata=public.course_verification_requirements.metadata||excluded.metadata,updated_at=now(); elsif spec->>'key' in ('agg_aspp','agg_rspp') then insert into public.course_verification_requirements(course_version_id,requirement_key,title,verification_mode,minimum_questions,minimum_options_per_question,passing_score_pct,required,completion_mode,metadata) values(v_version,'update_verification','Verifica aggiornamento','test_or_interview',10,3,70,true,'platform_or_external','{"in_relation_to_update_subject":true,"question_bank_complete":false}'::jsonb) on conflict(course_version_id,requirement_key) do update set verification_mode='test_or_interview',minimum_questions=10,minimum_options_per_question=3,passing_score_pct=70,metadata=public.course_verification_requirements.metadata||excluded.metadata,updated_at=now(); end if; end loop; for spec in select value from jsonb_array_elements($j$[{"key":"rspp_aspp_bsp1","title":"RSPP/ASPP - B-SP1 Agricoltura, silvicoltura e zootecnia - 16h","minutes":960,"ateco":"A 01-02","source":"dl_spp_agri"},{"key":"rspp_aspp_bsp2","title":"RSPP/ASPP - B-SP2 Pesca - 12h","minutes":720,"ateco":"A 03","source":"dl_spp_pesca"},{"key":"rspp_aspp_bsp3","title":"RSPP/ASPP - B-SP3 Costruzioni - 16h","minutes":960,"ateco":"F","source":"dl_spp_costruzioni"},{"key":"rspp_aspp_bsp5","title":"RSPP/ASPP - B-SP5 Chimico-petrolchimico - 16h","minutes":960,"ateco":"C 19-20","source":"dl_spp_chimico"}]$j$::jsonb) loop insert into public.courses(stable_key,title,family,description,nominal_minutes,certification_mode,active,metadata) values(spec->>'key',spec->>'title','RSPP/ASPP','Modulo B specialistico con libreria tecnica condivisa.',(spec->>'minutes')::int,'internal_learning',true,jsonb_build_object('blueprint_key','rspp_aspp_bsp','didactic_version','rspp-aspp-v2','ateco_reference',spec->>'ateco','attendance_min_pct',90,'delivery_constraint','physical_or_vcs','assessment','module_b_test_and_simulation','verification_scope','module_b_common_plus_applicable_specializations','shared_sector_learning_units',true,'learner_catalog_hidden',true,'requires_admin_review',true,'final_test_builder_paused',true)) on conflict(stable_key) do update set title=excluded.title,family=excluded.family,description=excluded.description,nominal_minutes=excluded.nominal_minutes,active=true,metadata=public.courses.metadata||excluded.metadata,updated_at=now() returning id into v_course; insert into public.course_versions(course_id,version_number,status,effective_from,syllabus_snapshot,normative_snapshot) values(v_course,1,'draft',date '2025-05-24',jsonb_build_object('didactic_version','rspp-aspp-v2','total_minutes',(spec->>'minutes')::int,'shared_sector_learning_units',true),jsonb_build_object('reference','Accordo Stato-Regioni 17/04/2025 Rep. 59/CSR','attendance_min_pct',90,'delivery','physical_or_vcs','assessment','test_and_simulation')) on conflict(course_id,version_number) do update set status='draft',syllabus_snapshot=excluded.syllabus_snapshot,normative_snapshot=excluded.normative_snapshot returning id into v_version; delete from public.course_module_units where module_id in(select id from public.course_modules where course_version_id=v_version); delete from public.course_modules where course_version_id=v_version; insert into public.course_modules(course_version_id,module_key,title,position,nominal_minutes) values(v_version,'sector',spec->>'title',1,(spec->>'minutes')::int) returning id into v_module; p:=0; for v_luv in select cmu.unit_version_id from public.courses c join public.course_versions cv on cv.course_id=c.id and cv.version_number=1 join public.course_modules cm on cm.course_version_id=cv.id join public.course_module_units cmu on cmu.module_id=cm.id where c.stable_key=spec->>'source' order by cm.position,cmu.position loop p:=p+1; insert into public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules) values(v_module,v_luv,p,true,0,true,'{"didactic_version":"rspp-aspp-v2","shared_sector_learning_unit":true,"module_b_verification_separate":true}'::jsonb); end loop; if p=0 then raise exception 'Missing shared sector learning units for %',spec->>'source'; end if; update public.integration_course_catalog set mapped_course_id=v_course,delivery_status='needs_configuration',metadata=metadata||jsonb_build_object('mapped_course_key',spec->>'key','didactic_version','rspp-aspp-v2','publication_blocked',true),updated_at=now() where source_system='safetytraining' and external_course_code=spec->>'key'; end loop; end $do$;